#include "native_helpers.hpp"
#include <sys/wait.h>
#include <sys/resource.h>
// Audit only after the complete measured reservation has ended. This controller
// has no solver launch or retry capability. Audit resource costs remain separate.
int main(int argc,char**argv){try{require(argc==5,"usage: audit_training CHECKER MATRIX CAMPAIGN NEW_AUDIT_DIR");files::path checker=files::canonical(argv[1]),campaign=argv[3],out=argv[4];auto matrix=read_json(argv[2]);require(files::is_regular_file(campaign/"stage_complete.json"),"Measured stage incomplete");require(files::create_directory(out),"Audit directory must be new");size_t checked=0,failed=0,skipped=0;std::string records="[";for(auto&row:matrix.at("rows").array){if(row.at("method").scalar!="ic")continue;auto id=row.at("id").scalar;auto dir=campaign/id;auto execution=read_json((dir/"execution.json").string());if(execution.at("status").scalar!="COMPLETED_VERIFIED"){skipped++;continue;}auto base=dir/"base.jsonl",trace=dir/"rank.jsonl",answers=dir/"answers.jsonl",receipt=out/(id+".json");auto seed=dec(num(row.at("rank_seed")));auto start=std::chrono::steady_clock::now();pid_t child=fork();require(child>=0,"fork failed");if(child==0){auto log=out/(id+".checker.log");int fd=open(log.c_str(),O_WRONLY|O_CREAT|O_EXCL,0644);if(fd<0)_exit(126);dup2(fd,1);dup2(fd,2);close(fd);execl(checker.c_str(),checker.c_str(),base.c_str(),trace.c_str(),answers.c_str(),seed.c_str(),receipt.c_str(),static_cast<char*>(nullptr));_exit(127);}int status;struct rusage usage{};require(wait4(child,&status,0,&usage)==child,"wait4 failed");auto wall=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();int code=WIFEXITED(status)?WEXITSTATUS(status):-1;if(code)failed++;checked++;if(records.size()>1)records+=",";std::ostringstream record;record<<"{\"id\":"<<qstr(id)<<",\"return_code\":"<<code<<",\"wall_s\":"<<std::setprecision(17)<<wall<<",\"cpu_user_s\":"<<usage.ru_utime.tv_sec+usage.ru_utime.tv_usec/1e6<<",\"cpu_system_s\":"<<usage.ru_stime.tv_sec+usage.ru_stime.tv_usec/1e6<<",\"peak_rss_bytes\":"<<uint64_t(usage.ru_maxrss)*1024<<",\"raw_wait_status\":"<<status<<",\"base_sha256\":"<<qstr(digest(base))<<",\"rank_sha256\":"<<qstr(digest(trace))<<",\"answers_sha256\":"<<qstr(digest(answers))<<"}";records+=record.str();}records+="]";std::ostringstream result;result<<"{\"kind\":\"n83_training_rank_audit_meter\",\"status\":"<<qstr(failed?"FAILED_AUDITS_PRESERVED":"ALL_COMPLETED_IC_AUDITED")<<",\"checked\":"<<checked<<",\"failed\":"<<failed<<",\"skipped_noncomplete_processes\":"<<skipped<<",\"costs_excluded_from_measured_solver_costs\":true,\"checker_sha256\":"<<qstr(digest(checker))<<",\"matrix_sha256\":"<<qstr(digest(argv[2]))<<",\"audits\":"<<records<<"}\n";create_new(out/"audit_meter.json",result.str());std::cout<<"Audited "<<checked<<", failed "<<failed<<", retained noncomplete "<<skipped<<"\n";return failed?1:0;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
